    65	     * New grass will be made into free adjacent locations.
    66	     * @param newGrass A list to return newly made grass.
    67	     */
    68	    protected void germinate(List<Actor> newGrass)
    69	    {
    70	        // New grass are made into adjacent locations.
    71	        // Get a list of adjacent free locations.
    72	        Field field = getField();
    73	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
    74	        for(int b = 0; b < free.size(); b++) {
    75	            Location loc = free.remove(0);
    76	            Grass young = new Grass(field, loc);
    77	            newGrass.add(young);
    78	        }
    79	    }
